$=jQuery.noConflict();

function capitalizeFirstLetter(string) {
  return string.charAt(0).toUpperCase() + string.slice(1);
}

/**
 * Handle the scrolling to different sections for the reviews and questions & answers sections.
 */
function scrollTo( selector, tab ) {
    jQuery(tab).trigger('click');
    if( jQuery(selector).offset() && jQuery(selector).offset().top ) {
        jQuery('html,body').animate({
            scrollTop: jQuery(selector).offset().top
        }, 1500);
    }
}

jQuery('.cp-').on('click', 'a', function() {
	BV.pixel.trackConversion({
		"type" : "FindAStore",
		"label" : "Single Product Page: " + cp_bazaarvoice_single_product_params.product_id,
		"value" : 1
	});
});

jQuery('.cp-purchase-link, .cp-purchase-links-menu > ul > li').on('click', 'a', function() {

	var storeType = jQuery(this).find('span span').data('bv-store');
	var type = "PurchaseLink"
	if (typeof storeType !== 'string' || storeType.length === 0){
		console.error('bv-store is not defined!');
	} else {
		type += capitalizeFirstLetter(storeType);
	}
	BV.pixel.trackConversion({
		"type" : type,
		"label" : "Single Product Page: " + cp_bazaarvoice_single_product_params.product_id,
		"value" : 1
	});
});

